 "content": "from math import gcd


def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 1]
    if len(points) < 2:
        return out
    points.sort()
    row_steps = [points[i + 1][0] - points[i][0] for i in range(len(points) - 1)]
    col_steps = [points[i + 1][1] - points[i][1] for i in range(len(points) - 1)]
    step_r = 0
    step_c = 0
    for d in row_steps:
        step_r = gcd(step_r, d)
    for d in col_steps:
        step_c = gcd(step_c, d)
    if step_r <= 0 or step_c <= 0:
        return out
    r, c = points[-1]
    nr, nc = r + step_r, c + step_c
    while nr < len(out) and nc < len(out[0]):
        if out[nr][nc] == 0:
            out[nr][nc] = 2
        nr += step_r
        nc += step_c
    return out
